-- W05: opt-in additions only. Existing manual choices/tombstones never overwritten.
do $$begin if not exists(select 1 from feture_seed.environment where singleton and project_ref='anrhayozrhrmiwexmbhw' and stage='prelaunch') then raise exception 'feture_prelaunch_required';end if;end$$;
create table public.feture_test_map_rules(
 definition_hash text not null check(definition_hash ~ '^[a-f0-9]{64}$'),dimension_id text not null,
 interest_id text not null references public.feture_interests(id),reason text not null check(char_length(reason) between 1 and 600),
 primary key(definition_hash,dimension_id,interest_id));
create index feture_test_map_rule_interest on public.feture_test_map_rules(interest_id);
create table public.feture_test_map_operations(
 account_hash text not null references public.feture_profiles(account_hash) on delete cascade,operation_id uuid not null,
 attempt_id uuid not null references public.feture_test_attempts(id) on delete cascade,payload_hash text not null check(payload_hash ~ '^[a-f0-9]{64}$'),
 applied_count integer not null check(applied_count between 1 and 6),primary key(account_hash,operation_id));
create index feture_test_map_operation_attempt on public.feture_test_map_operations(attempt_id);
create function public.feture_test_map_command(p_owner text,p_command jsonb) returns jsonb
language plpgsql security invoker set search_path=pg_catalog,public as $$
declare act text:=p_command->>'action';a public.feture_test_attempts;v public.feture_test_versions;op uuid;h text;r public.feture_test_map_operations;items jsonb;item jsonb;chosen jsonb;ids text[];at_time timestamptz;
begin
 if p_owner is null or p_owner !~ '^[a-f0-9]{32}$' or jsonb_typeof(p_command) is distinct from 'object' or act is null or act not in('tests.mapPreview','tests.mapApply') then return jsonb_build_object('ok',false,'error','invalid_request');end if;
 -- Same order as questionnaire writes; owner profile lock also serializes manual map/history writes.
 perform pg_advisory_xact_lock(hashtextextended('feture-tests-owner:'||p_owner,0));
 select * into a from public.feture_test_attempts where id=(p_command->>'attemptId')::uuid and account_hash=p_owner and status='completed';
 if a.id is null then return jsonb_build_object('ok',false,'error','resource_not_found');end if;
 select * into v from public.feture_test_versions where id=a.version_id;
 if act='tests.mapApply' then
  op:=(p_command->>'operationId')::uuid;chosen:=p_command->'selected';
  if op is null or jsonb_typeof(chosen) is distinct from 'array' or jsonb_array_length(chosen) not between 1 and 6 then return jsonb_build_object('ok',false,'error','invalid_request');end if;
  if exists(select 1 from jsonb_array_elements(chosen) x where jsonb_typeof(x) is distinct from 'object' or not(x ?& array['interestId','expectedRevision']) or (select count(*) from jsonb_object_keys(x))<>2 or jsonb_typeof(x->'interestId') is distinct from 'string' or x->>'interestId' !~ '^interest-[1-9][0-9]{0,2}-[1-9][0-9]{0,2}$' or x->'expectedRevision' is distinct from '0'::jsonb) then return jsonb_build_object('ok',false,'error','invalid_request');end if;
  select array_agg(x->>'interestId' order by x->>'interestId') into ids from jsonb_array_elements(chosen) x;
  if cardinality(ids)<>(select count(distinct x) from unnest(ids) x) then return jsonb_build_object('ok',false,'error','invalid_request');end if;
  h:=encode(sha256(convert_to(p_command::text,'UTF8')),'hex');
  perform 1 from public.feture_profiles where account_hash=p_owner for update;
  select * into r from public.feture_test_map_operations where account_hash=p_owner and operation_id=op;
  if found then
   if r.payload_hash<>h then return jsonb_build_object('ok',false,'error','operation_conflict');end if;
   return jsonb_build_object('ok',true,'replayed',true,'applied',r.applied_count);
  end if;
 end if;
 -- Exact definition fingerprint: editing a question/weight/text invalidates the reviewed mapping.
 -- Low/insufficient scores are never interpreted as a rejection or permission.
 select coalesce(jsonb_agg(jsonb_build_object('interestId',x.interest_id,'title',t.title,'reason',x.reason,'dimensionId',x.dimension_id,
  'available',not exists(select 1 from public.feture_interest_states s where s.account_hash=p_owner and s.interest_id=x.interest_id),
  'blockedReason',case when exists(select 1 from public.feture_interest_states s where s.account_hash=p_owner and s.interest_id=x.interest_id) then 'existing_choice' else null end,
  'next',jsonb_build_object('stance','curious','experience','unspecified','boundary','none','boundaryNote',null,'intensity',null,'visibility','private','useForDiscovery',false)) order by x.interest_id),'[]') into items
 from public.feture_test_map_rules x join public.feture_interests t on t.id=x.interest_id
 where x.definition_hash=encode(sha256(convert_to(v.definition::text,'UTF8')),'hex')
 and exists(select 1 from jsonb_array_elements(a.result->'dimensions') dim where dim->>'id'=x.dimension_id and dim->>'level' in('mid','high'));
 if act='tests.mapPreview' then return jsonb_build_object('ok',true,'attemptId',a.id,'versionId',v.id,'items',items);end if;
 foreach h in array ids loop
  select x into item from jsonb_array_elements(items) x where x->>'interestId'=h;
  if item is null then return jsonb_build_object('ok',false,'error','invalid_request');end if;
  if item->>'available'<>'true' then return jsonb_build_object('ok',false,'error','map_changed');end if;
 end loop;
 -- All checks finish before the first write; selection is one atomic transaction.
 at_time:=clock_timestamp();
 foreach h in array ids loop
  insert into public.feture_interest_states(account_hash,interest_id,stance,experience,boundary,boundary_note,intensity,visibility,use_for_discovery,revision,source,test_version,deleted,updated_at)
  values(p_owner,h,'curious','unspecified','none',null,null,'private',false,1,'test',v.id,false,at_time);
 end loop;
 insert into public.feture_test_map_operations(account_hash,operation_id,attempt_id,payload_hash,applied_count)
 values(p_owner,op,a.id,encode(sha256(convert_to(p_command::text,'UTF8')),'hex'),cardinality(ids));
 return jsonb_build_object('ok',true,'replayed',false,'applied',cardinality(ids));
exception when invalid_text_representation or numeric_value_out_of_range then return jsonb_build_object('ok',false,'error','invalid_request');
end$$;
alter table public.feture_test_map_rules enable row level security;
alter table public.feture_test_map_operations enable row level security;
revoke all on public.feture_test_map_rules,public.feture_test_map_operations from public,anon,authenticated,service_role;
grant select on public.feture_test_map_rules to service_role;
grant select,insert on public.feture_test_map_operations to service_role;
revoke all on function public.feture_test_map_command(text,jsonb) from public,anon,authenticated;
grant execute on function public.feture_test_map_command(text,jsonb) to service_role;

