insert into public.feture_test_map_rules values(encode(sha256(convert_to(($definition${"id":"dynamics","title":"Роли и динамика","description":"Как тебе комфортнее распределять инициативу и договорённости. Любой вопрос можно пропустить. Это опросник для размышления, а не научная диагностика.","dimensions":[{"id":"initiative","title":"Инициатива","low":"Тебе может быть комфортнее откликаться на предложения. Это не обязанность оставаться в одной роли.","mid":"Похоже, инициатива зависит от ситуации. Можно обсудить, когда хочется предлагать, а когда — откликаться.","high":"В ответах заметен интерес проявлять инициативу. Это не даёт права решать за другого человека."},{"id":"agreement","title":"Ясность договорённостей","low":"Тебе может подходить меньше заранее заданных правил. Даже при спонтанности нужно обсуждать согласие и право остановиться.","mid":"Тебе может подходить сочетание договорённостей и свободы. Полезно заранее назвать то, что менять нельзя.","high":"В ответах важна ясность ожиданий. Подробные договорённости могут помогать комфорту, но не заменяют согласие в моменте."}],"questions":[{"id":"initiative-1","prompt":"Мне нравится предлагать, как провести время вместе.","dimension":"initiative","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"initiative-2","prompt":"Мне комфортно первым начинать разговор о желаниях.","dimension":"initiative","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"initiative-3","prompt":"Мне интересно задавать направление совместному исследованию.","dimension":"initiative","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"initiative-4","prompt":"Мне удобно первым предлагать несколько вариантов на выбор, оставляя решение общим.","dimension":"initiative","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"agreement-1","prompt":"Мне спокойнее, когда ожидания обсуждены заранее.","dimension":"agreement","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"agreement-2","prompt":"Мне важно заранее понимать, что можно остановить без объяснения причин.","dimension":"agreement","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"agreement-3","prompt":"Я предпочитаю проговаривать, кто за что отвечает.","dimension":"agreement","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"agreement-4","prompt":"Перед новым опытом мне хочется обсудить возможные изменения плана.","dimension":"agreement","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]}]}$definition$::jsonb)::text,'UTF8')),'hex'),'initiative','interest-1-7','Размышления об инициативе могут стать поводом изучить партнёрскую динамику.');
