insert into public.feture_test_map_rules values(encode(sha256(convert_to(($definition${"id":"closeness","title":"Близость и пространство","description":"Что помогает ощущать связь, сохраняя комфортную дистанцию. Любой вопрос можно пропустить. Это опросник для размышления, а не научная диагностика.","dimensions":[{"id":"connection","title":"Эмоциональная связь","low":"В ответах сейчас меньше потребности в частом эмоциональном обмене. Можно искать удобные способы связи без давления.","mid":"Похоже, степень близости зависит от ситуации. Стоит обсудить, какие проявления поддержки подходят именно тебе.","high":"В ответах заметна потребность в эмоциональной связи. Другой человек может проявлять её иначе; лучше назвать конкретные ожидания."},{"id":"space","title":"Личное пространство","low":"Сейчас отдельное время может быть менее значимым для тебя. Это не означает, что у тебя нет границ.","mid":"Похоже, тебе нужен гибкий баланс совместного и личного времени. Его можно пересматривать.","high":"В ответах важно личное пространство. Можно договориться о времени на себя без трактовки его как отвержения."}],"questions":[{"id":"connection-1","prompt":"Мне важно регулярно делиться переживаниями с близким человеком.","dimension":"connection","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"connection-2","prompt":"Тёплые слова помогают мне чувствовать связь.","dimension":"connection","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"connection-3","prompt":"Мне 