insert into public.feture_test_map_rules values(encode(sha256(convert_to(($definition${"id":"sensations","title":"Ощущения и любопытство","description":"Какие условия помогают исследовать ощущения без обязательства пробовать что-либо. Любой вопрос можно пропустить. Это опросник для размышления, а не научная диагностика.","dimensions":[{"id":"novelty","title":"Новизна","low":"В ответах сейчас ближе знакомые ощущения. Нет необходимости расширять опыт ради чьих-то ожиданий.","mid":"Интерес к новизне зависит от условий. Можно начать с разговора или наблюдения без обязательства действовать.","high":"В ответах есть любопытство к новому. Оно не означает готовности к любой теме и не отменяет отдельных границ."},{"id":"predictability","title":"Предсказуемость","low":"В ответах меньше потребности в подготовке. Полезно всё равно обозначать согласие, ограничения и возможность остановки.","mid":"Тебе может подходить немного подготовки и возможность менять план. Стоит назвать условия, которые помогают расслабиться.","high":"В ответах важны подготовка и предсказуемость. Можно заранее обсудить обстановку и темп без обязанности продолжать."}],"questions":[{"id":"novelty-1","prompt":"Мне интересно узнавать о незнакомых ощущениях.","dimension":"novelty","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"novelty-2","prompt":"Мне нравится рассматривать разные способы совместного отдыха.","dimension":"novelty","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"novelty-3